//! 爱的小窝: the nest a bound pair keeps — timeline, albums, media,
//! anniversaries, the shared list, the pet and the saved AI pieces.
//!
//! Generated by tool/gen_nest_http.py from a route table. Thirty handlers that
//! differ only in verb, message and rate-limit class: written out by hand, the
//! one transposed name that still compiles would route a call to the wrong
//! thing, and nothing would catch it.
//!
//! Every request names its `spaceId`; membership is resolved from it in the
//! service, so a stale client cannot write into a space it was unbound from.

use axum::{
    extract::State,
    routing::{get, post},
    Json, Router,
};

use super::{middleware::RequestMetadata, validation::ProtoQuery, AppResult, AppState};
use synctv_api_common::impls::EndpointRateLimitCategory;
