// ---------------------------------------------------------- media objects ---
// Photo and video bytes. Both directions are HTTP-only, like every other object
// route in the app: a stream does not belong in a proto message.

#[derive(Debug, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct CoupleMediaObjectPath {
    media_id: String,
}

#[derive(Debug, Default, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct CoupleMediaUploadQuery {
    space_id: String,
    #[serde(default)]
    kind: i32,
    #[serde(default)]
    album_id: Option<String>,
    #[serde(default)]
    memory_id: Option<String>,
    #[serde(default)]
    caption: Option<String>,
    #[serde(default)]
    taken_on: Option<String>,
    #[serde(default)]
    width: Option<i32>,
    #[serde(default)]
    height: Option<i32>,
}

/// Stores one photo or video and files it into the nest.
pub async fn upload_couple_media_object(
    request_meta: RequestMetadata,
    State(state): State<AppState>,
    axum::extract::Query(query): axum::extract::Query<CoupleMediaUploadQuery>,
    headers: axum::http::HeaderMap,
    body: axum::body::Bytes,
) -> AppResult<Json<synctv_proto::client::AddCoupleMediaResponse>> {
    let mime = headers
        .get(axum::http::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .unwrap_or("application/octet-stream")
        .to_string();
    let executor = state.shared_api_runtime.client_api.clone();
    let client_api = state.shared_api_runtime.client_api.clone();
    let media = executor
        .execute_user_endpoint(
            &request_meta.0,
            EndpointRateLimitCategory::Write,
            |auth| async move {
                client_api
                    .upload_couple_media_object(
                        &auth.user_id(),
                        &query.space_id,
                        query.kind,
                        &mime,
                        body.to_vec(),
                        query.album_id.as_deref(),
                        query.memory_id.as_deref(),
                        query.caption.as_deref().unwrap_or_default(),
                        query.taken_on.as_deref().unwrap_or_default(),
                        query.width.unwrap_or_default(),
                        query.height.unwrap_or_default(),
                    )
                    .await
            },
        )
        .await
        .map_err(super::error::map_api_error)?;
    Ok(Json(synctv_proto::client::AddCoupleMediaResponse {
        media: Some(media),
    }))
}

/// Streams one item back to a member of its space.
///
/// No token in the URL: the caller is authenticated as themselves and checked
/// against the space, so a link to a couple photo is worthless to anyone else
/// even if it leaks into a log or a referrer.
pub async fn get_couple_media_object(
    request_meta: RequestMetadata,
    State(state): State<AppState>,
    axum::extract::Path(path): axum::extract::Path<CoupleMediaObjectPath>,
) -> AppResult<axum::response::Response> {
    let executor = state.shared_api_runtime.client_api.clone();
    let client_api = state.shared_api_runtime.client_api.clone();
    let download = executor
        .execute_user_endpoint(
            &request_meta.0,
            EndpointRateLimitCategory::Read,
            |auth| async move {
                client_api
                    .couple_media_object_download(&auth.user_id(), &path.media_id)
                    .await
            },
        )
        .await
        .map_err(super::error::map_api_error)?;
    // Immutable: a media row never points at a different object once written.
    super::file_object_download_response(download, Some("private, max-age=31536000, immutable"))
}
